    """
    Implements a basic regex matching algorithm using recursion and memoization.
    Supports literal characters, '.' (any char), '*' (zero or more of preceding), and '+' (one or more of preceding).
    """
    memo = {}

    def dp(p_index: int, t_index: int) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]
        if p_index == len(pattern):
            result = t_index == len(text)
            memo[(p_index, t_index)] = result
            return result

        first_match = t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.')

        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
                match_zero = dp(p_index + 2, t_index)
                match_more = first_match and dp(p_index, t_index + 1)
                result = match_zero or match_more
                memo[(p_index, t_index)] = result
                return result
            elif pattern[p_index + 1] == '+':
                if first_match:
                    result = dp(p_index, t_index + 1) or dp(p_index + 2, t_index)
                    memo[(p_index, t_index)] = result
                    return result

        result = first_match and dp(p_index + 1, t_index + 1)
        memo[(p_index, t_index)] = result
        return result

    return dp(0, 0)

