    Implements a basic regex matching algorithm using an iterative Dynamic Programming approach.
    Supports literal characters, '.' (any char), '*' (zero or more of the preceding), and '+' (one or more of the preceding).
    """
    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]
        elif pattern[i - 1] == '+':
            dp[i][0] = False

